MANIFEST = json.loads(zlib.decompress(base64.b64decode(_MANIFEST)).decode())


def repo_root(start: Path) -> Path:
    for d in [start, *start.parents]:
        if (d / ".git").exists() or (d / "package.json").exists():
            return d
    return start


def main() -> int:
    check = "--check" in sys.argv[1:]
    design = repo_root(Path(__file__).resolve().parent) / "design"
    if not (design / "reference" / "fonts" / "Geist-Variable.woff2").exists():
        print("note: design/reference/fonts/ is missing; the boards need it to render in Geist")
    if check:
        bad = []
        for rel, digest in sorted(MANIFEST.items()):
            path = design / rel
            if not path.exists():
                bad.append(f"missing  {rel}")
            elif hashlib.sha256(path.read_bytes()).hexdigest() != digest:
                bad.append(f"changed  {rel}")
        for line in bad:
            print(line)
        print(f"{len(MANIFEST) - len(bad)} of {len(MANIFEST)} files match")
        return 1 if bad else 0
    files = json.loads(zlib.decompress(base64.b64decode(_BLOB)).decode())
    for rel in sorted(files):
        data = base64.b64decode(files[rel])
        if hashlib.sha256(data).hexdigest() != MANIFEST[rel]:
            print(f"corrupt blob entry: {rel}")
            return 1
        path = design / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
    print(f"wrote {len(files)} files under {design}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
